-- Migration v6.5 — engine figures checked against published specifications
--
-- The 330 engine rows that were in the catalogue before the market snapshot
-- (the ones written by hand or by the AI curator) were checked on 2026-11-14
-- against manufacturer data, the German Wikipedia technical tables and
-- auto-data.net: that the model had the engine, its fuel, size, power, torque,
-- gearbox, and that consumption and CO2 are within 20% of the published range.
--
--   301 rows confirmed
--   26 rows corrected (below)
--   1 row removed
--   2 rows the check could not settle: left as they were, with no source
--
-- Each checked row now says so in `source`, with the page it was read on.
-- Reliability and maintenance were not part of this check.
--
-- One whole-table fix on top: v61 marked a hybrid as plug-in when its
-- consumption was under 4 L/100 km. A Yaris or Mazda 2 hybrid does 3.8 without
-- a plug. A hybrid is now plug-in only when its name says so or it consumes
-- under 2.5 L.
--
-- Rows are found by brand, model and engine code. Idempotent.

BEGIN;

-- removed: the Q2 was never sold with the 95 cv "25 TFSI"
WITH gone AS (
    SELECT e.id FROM engines e JOIN vehicle_models vm ON vm.id = e.model_id JOIN brands b ON b.id = vm.brand_id
    WHERE b.name = 'Audi' AND vm.name = 'Q2' AND e.code = '25 TFSI 95'
), a AS (DELETE FROM engine_issues WHERE engine_id IN (SELECT id FROM gone)),
   b AS (UPDATE market_price_stats SET engine_id = NULL WHERE engine_id IN (SELECT id FROM gone)),
   c AS (UPDATE market_price_stats_history SET engine_id = NULL WHERE engine_id IN (SELECT id FROM gone)),
   d AS (UPDATE reliability_evidence SET engine_id = NULL WHERE engine_id IN (SELECT id FROM gone)),
   f AS (UPDATE reliability_scores_history SET engine_id = NULL WHERE engine_id IN (SELECT id FROM gone)),
   g AS (DELETE FROM import_cost_estimates WHERE engine_id IN (SELECT id FROM gone))
DELETE FROM engines WHERE id IN (SELECT id FROM gone);

UPDATE engines e
SET code              = COALESCE(v.code, e.code),
    plug_in           = COALESCE(v.plug_in, e.plug_in),
    displacement_cc   = COALESCE(v.displacement_cc, e.displacement_cc),
    power_hp          = COALESCE(v.power_hp, e.power_hp),
    torque_nm         = COALESCE(v.torque_nm, e.torque_nm),
    transmission      = COALESCE(v.transmission, e.transmission),
    consumption_mixed = COALESCE(v.consumption_mixed, e.consumption_mixed),
    co2_emissions     = COALESCE(v.co2_emissions, e.co2_emissions),
    source = v.source
FROM (VALUES
    ('Citroën', 'C3', '1.2 PureTech 83', NULL::text, NULL::boolean, NULL::int, NULL::int, 118::int, NULL::text, NULL::numeric, NULL::int, 'corrigido 2026-11-14: https://de.wikipedia.org/wiki/Citroën_C3'),
