) AS v(brand, model, old_code, code, plug_in, displacement_cc, power_hp, torque_nm, transmission, consumption_mixed, co2_emissions, source)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE e.model_id = vm.id AND e.code = v.old_code;

UPDATE engines
SET plug_in = FALSE
WHERE plug_in AND fuel_type = 'hibrido' AND consumption_mixed >= 2.5
  AND code !~* '(phev|plug|e-hybrid|tfsie|recharge)';

COMMIT;

-- Verify: engines still without a checked source.
SELECT b.name AS brand, vm.name AS model, e.code, e.source
FROM engines e JOIN vehicle_models vm ON vm.id = e.model_id JOIN brands b ON b.id = vm.brand_id
WHERE e.source IS NULL OR e.source LIKE 'IA (%'
ORDER BY 1, 2, 3;
